function mergeArrays(arr1, arr2) {
  const set = new Set();

  // Iterate through both arrays and add unique objects to the set
  const uniqueObjects = [...arr1, ...arr2].reduce((acc, obj) => {
    const key = JSON.stringify([obj.stepId, obj.fieldId]);
    if (!set.has(key)) {
      set.add(key);
      acc.push(obj);
    }
    return acc;
  }, []);

  // Merge messages from both objects if not available in the first one
  uniqueObjects.forEach(obj => {
    if (!obj.hasOwnProperty('message')) {
      const matchingObj = arr2.find(o => o.stepId === obj.stepId && o.fieldId === obj.fieldId);
      if (matchingObj) obj.message = matchingObj.message;
    }
  });

  return uniqueObjects;
}

