function timeAgo(postDate: Date): string {
  const currentDate = new Date();
  const secondsAgo = Math.floor((currentDate.getTime() - postDate.getTime()) / 1000);

  const minute = 60;
  const hour = minute * 60;
  const day = hour * 24;
  const week = day * 7;
  const month = day * 30;
  const year = day * 365;

  if (secondsAgo < minute) {
    return `${Math.floor(secondsAgo)} seconds ago`;
  } else if (secondsAgo < hour) {
    return `${Math.floor(secondsAgo / minute)} minutes ago`;
  } else if (secondsAgo < day) {
    return `${Math.floor(secondsAgo / minute / 60)} hours ago`;
  } else if (secondsAgo < week) {
    return `${Math.floor(secondsAgo / day)} days ago`;
  } else if (secondsAgo < month) {
    return `${Math.floor(secondsAgo / day / 7)} weeks ago`;
  } else if (secondsAgo < year) {
    return `${Math.floor(secondsAgo / day / 30)} months ago`;
  } else {
    return `${Math.floor(secondsAgo / day / 365)} years ago`;
  }
}

